#!/usr/bin/env python3
"""Save pinned SMLib parameter curves for cylinder and sphere cuts as untrusted Catallax test inputs."""
import argparse
from pathlib import Path
import subprocess

PIN = "c9c5979f04cea8c38213004d4f04df0dcfb40d05"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("oracle", type=Path, help="compiled oracle.cpp driver")
    args = parser.parse_args()
    folder = Path(__file__).resolve().parent
    for surface in ("cylinder", "sphere"):
        for cut in ("loft", "lofttight", "hill", "tiny", "tangent"):
            case = f"{surface}-{cut}"
            result = subprocess.run([str(args.oracle.resolve()), case], check=True,
                                    capture_output=True, text=True, timeout=300)
            rows = result.stdout.splitlines()
            assert any(row.startswith("STATUS 1000 CURVES ") for row in rows), result.stdout
            data = [row for row in rows if row.startswith(("STATUS ", "CURVE ", "KNOTS", "POINTS"))]
            (folder / f"{case}.txt").write_text(
                f"# Generated by oracle.cpp using NVIDIA-Omniverse/usd-brep {PIN}\n"
                + "\n".join(data) + "\n")


if __name__ == "__main__":
    main()
